pub enum RepeatDowhileSubAction {
    IfPlayer(IfPlayer),
    IfEntity(IfEntity),
    IfVar(IfVar),
    IfGame(IfGame),
}

impl RepeatDowhileSubAction {
    fn to_wire(&self) -> Value {
        match self {
            Self::IfPlayer(action) => action.to_wire(),
            Self::IfEntity(action) => action.to_wire(),
            Self::IfVar(action) => action.to_wire(),
            Self::IfGame(action) => action.to_wire(),
        }
    }

    fn sub_action_wire_name(&self) -> String {
        match self {
            Self::IfPlayer(action) => action.sub_action_wire_name(),
            Self::IfEntity(action) => action.sub_action_wire_name(),
            Self::IfVar(action) => action.sub_action_wire_name(),
            Self::IfGame(action) => action.sub_action_wire_name(),
        }
    }
}

pub enum RepeatWhileSubAction {
    IfPlayer(IfPlayer),
    IfEntity(IfEntity),
    IfVar(IfVar),
    IfGame(IfGame),
}

