impl super::super::typed::WireAction for EntityAction {
    fn to_wire_value(&self) -> Value {
        self.to_wire()
    }
    fn sub_action_wire_name(&self) -> String {
        Self::sub_action_wire_name(self)
    }
}

fn encode_action(
    block: &str,
    action: &str,
    sub_action_name: &str,
    arguments: Vec<Option<Item>>,
    tags: &[(u8, &'static str, Option<&'static str>, &'static str)],
    sub_action: Option<(Value, String)>,
) -> Value {
    let mut items: Vec<Value> = arguments
        .into_iter()
        .enumerate()
        .filter_map(|(slot, argument)| {
            argument.map(|argument| json!({"item": argument.to_value(), "slot": slot}))
        })
        .collect();
    for (slot, name, option, owner_action) in tags {
        if let Some(option) = option {
            items.push(json!({"item": {"version": 0, "id": "bl_tag", "data": {"tag": name, "option": option, "action": owner_action, "block": block}}, "slot": slot}));
        }
    }
    items.sort_by_key(|item| item.get("slot").and_then(Value::as_u64).unwrap_or(0));
    let mut value =
        json!({"id": "block", "block": block, "action": action, "args": {"items": items}});
    if !sub_action_name.is_empty() {
        value["subAction"] = json!(sub_action_name);
    }
    if let Some((child, child_sub_action)) = sub_action {
        if let Some(child_items) = child
            .get("args")
            .and_then(|args| args.get("items"))
            .and_then(Value::as_array)
        {
            value["args"]["items"]
                .as_array_mut()
                .unwrap()
                .extend(child_items.iter().cloned());
        }
        value["subAction"] = json!(child_sub_action);
    }
    value
}

fn encode_dynamic(
    block: &str,
    name: &str,
    arguments: &[Item],
    tags: &[(u8, &'static str, Option<&'static str>, &'static str)],
) -> Value {
    let mut items: Vec<Value> = arguments
        .iter()
        .enumerate()
        .map(|(slot, argument)| json!({"item": argument.to_value(), "slot": slot}))
        .collect();
    for (slot, tag, option, owner_action) in tags {
        if let Some(option) = option {
            items.push(json!({"item": {"version": 0, "id": "bl_tag", "data": {"tag": tag, "option": option, "action": owner_action, "block": block}}, "slot": slot}));
        }
    }
    items.sort_by_key(|item| item.get("slot").and_then(Value::as_u64).unwrap_or(0));
    json!({"id": "block", "block": block, "data": name, "args": {"items": items}})
}
